mapper.insert:





SELECT
    #{OFFCS_SGNNG_NO} AS OFFCS_SGNNG_NO     /* 직인서명번호 */
    ,NVL(MAX(MNG_SN),0)+1 AS MNG_SN          /* 관리일련번호 */
FROM SAA230     /* 직인서명상세 */

WHERE 1=1
    AND OFFCS_SGNNG_NO = #{OFFCS_SGNNG_NO}






SELECT
    NVL(MAX(OFFCS_SGNNG_NO),0)+1 AS OFFCS_SGNNG_NO  /* 직인서명번호 */
    ,'1' AS MNG_SN                                  /* 관리일련번호 */
FROM SAA230     /* 직인서명상세 */






/* insertOffcsSgnng - Lee Sanghoon */

INSERT INTO SAA230 (        /* 직인서명상세 */
    OFFCS_SGNNG_NO      /* 직인서명번호 */
    ,MNG_SN             /* 관리일려번호 */
    ,OFFCS_SGNNG_SE_CD  /* 직인서명구분코드 */
    ,ATFINO             /* 첨부파일번호 */
    ,ATCMFL_MNG_SN      /* 첨부파일관리일련번호 */
    ,USE_BGNG_DT        /* 사용시작일시 */
    ,USE_YN             /* 사용여부 */
) VALUES (
    #{OFFCS_SGNNG_NO}
    ,#{MNG_SN}
    ,#{OFFCS_SGNNG_SE_CD}
    ,#{ATFINO}
    ,#{ATCMFL_MNG_SN}
    ,SYSDATE + 1/24/60/60
    ,#{USE_YN}
)

mapper.update:

/* setOffcsSgnng - Lee SangHoon */

UPDATE SAA230 /* 직인서명상세 */ SET
	USE_END_DT = SYSDATE,
	USE_YN = 'N'
WHERE OFFCS_SGNNG_NO = #{OFFCS_SGNNG_NO}
   AND USE_YN = 'Y'

mapper.delete:

/* deleteOffcsSgnng - Lee SangHoon */

DELETE FROM SAA230  /* 직인서명상세 */
WHERE OFFCS_SGNNG_NO = #{OFFCS_SGNNG_NO}
    AND MNG_SN = #{MNG_SN}

mapper.update:

/* updateOffcsSgnggNoToInst - Lee SangHoon */

UPDATE SAA000 /* 통합기관 */ SET
    OFFCS_SGNNG_NO = #{OFFCS_SGNNG_NO}
WHERE INST_NO = #{INST_NO}

